import { NextResponse } from 'next/server';
import { requireUser } from '@/lib/auth';
export async function POST(req:Request){const {supabase,user,profile}=await requireUser();if(!user||!profile)return NextResponse.json({error:'Unauthorized'},{status:401});const b=await req.json();if(!String(b.name||'').trim())return NextResponse.json({error:'Name is required'},{status:400});const rate=Math.max(0,Math.min(100,Number(b.commission_rate||0)));const {data,error}=await supabase.from('vendors').insert({organization_id:profile.organization_id,name:b.name,contact_email:b.contact_email||null,contact_phone:b.contact_phone||null,status:'active',commission_rate:rate,source_url:b.source_url||null}).select().single();if(error)return NextResponse.json({error:error.message},{status:400});return NextResponse.json({vendor:data});}
